    id: 'xm-steel-swell', name: 'Steel Swell', ref: 'In the style of Daniel Lanois — "Frozen" (Belladonna)', artist: 'Daniel Lanois',
    tags: ['lead', 'ambient', '00s'], level: 2,
    blurb: 'A warm, soft lead that swells in on every note and bends up or down into the next, like a pedal steel.',
